sys_script_client.script:
// Client Script: onChange
// Table: Student Profile (x_1983287_studen_0_student_profile)
// Field: department

function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Get the display value of the selected Department
    g_form.getReference('student_name', function(studentRecord) {
        if (studentRecord && studentRecord.email) {
            // Auto-populate email field with reference student email reference
            g_form.setValue('email', studentRecord.email);
        } else {
            g_form.clearValue('email'); // Clear if no student found
        }
    });
}
